namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1,
                Title = "Classic Margherita Pizza",
                Category = "Italian",
                Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
                Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly over the dough.\n4. Tear mozzarella into pieces and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
                Ratings = [5, 4, 5, 4, 5]
            },
            new Recipe
            {
                Id = 2,
                Title = "Spaghetti Carbonara",
                Category = "Italian",
                Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper",
                Steps = "1. Cook spaghetti in salted boiling water until al dente.\n2. Crisp guanciale in a pan over medium heat.\n3. Whisk eggs with grated pecorino and black pepper.\n4. Toss hot pasta with guanciale, remove from heat.\n5. Stir in egg mixture quickly, tossing to create a creamy sauce.\n6. Serve immediately with extra pecorino.",
                Ratings = [5, 5, 4]
            },
            new Recipe
            {
                Id = 3,
                Title = "Chicken Tikka Masala",
                Category = "Indian",
                Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nCrushed tomatoes\nHeavy cream\nGarlic\nGinger\nOnion",
                Steps = "1. Marinate chicken in yogurt, garam masala, turmeric, and cumin for 1 hour.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger in a pan.\n4. Add crushed tomatoes and simmer 15 minutes.\n5. Stir in cream and spices, add chicken pieces.\n6. Simmer 10 minutes and serve with basmati rice.",
                Ratings = [5, 4, 4, 5]
            },
            new Recipe
            {
                Id = 4,
                Title = "Vegetable Biryani",
                Category = "Indian",
                Ingredients = "Basmati rice\nMixed vegetables\nOnion\nYogurt\nBiryani masala\nSaffron\nMint\nCilantro\nGhee",
                Steps = "1. Soak basmati rice for 30 minutes, then parboil.\n2. Sauté sliced onions in ghee until golden.\n3. Cook vegetables with biryani masala and yogurt.\n4. Layer rice and vegetable mixture in a pot.\n5. Add saffron milk, mint, and cilantro.\n6. Cover tightly and cook on low heat for 20 minutes.",
                Ratings = [4, 5, 4]
            },
            new Recipe
            {
                Id = 5,
                Title = "Tacos al Pastor",
                Category = "Mexican",
                Ingredients = "Pork shoulder\nPineapple\nChili peppers\nOnion\nCilantro\nCorn tortillas\nLime\nAchiote paste",
                Steps = "1. Blend achiote paste with chili peppers and pineapple juice for marinade.\n2. Marinate sliced pork for at least 2 hours.\n3. Grill pork and pineapple slices until charred.\n4. Chop pork and pineapple into small pieces.\n5. Warm tortillas on a skillet.\n6. Assemble tacos with pork, pineapple, onion, cilantro, and lime.",
                Ratings = [5, 5, 5, 4]
            },
            new Recipe
            {
                Id = 6,
                Title = "Guacamole",
                Category = "Mexican",
                Ingredients = "Avocados\nLime juice\nCilantro\nOnion\nTomato\nJalapeño\nSalt",
                Steps = "1. Halve avocados and remove pits.\n2. Mash avocado flesh in a bowl to desired consistency.\n3. Dice onion, tomato, jalapeño, and cilantro.\n4. Mix everything together with lime juice and salt.\n5. Taste and adjust seasoning.\n6. Serve immediately with tortilla chips.",
                Ratings = [4, 4, 5]
            },
            new Recipe
            {
                Id = 7,
                Title = "Pad Thai",
                Category = "Asian",
                Ingredients = "Rice noodles\nShrimp or tofu\nEggs\nBean sprouts\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar",
                Steps = "1. Soak rice noodles in warm water for 30 minutes.\n2. Mix tamarind paste, fish sauce, and sugar for the sauce.\n3. Stir-fry shrimp or tofu in a wok until cooked.\n4. Push to the side and scramble eggs in the wok.\n5. Add noodles and sauce, toss until well coated.\n6. Garnish with bean sprouts, peanuts, green onions, and lime.",
                Ratings = [5, 4, 5, 5]
            },
            new Recipe
            {
                Id = 8,
                Title = "Chocolate Lava Cake",
                Category = "Desserts",
                Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
                Steps = "1. Preheat oven to 425°F (220°C) and butter ramekins.\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick and pale.\n4. Fold chocolate mixture into eggs, then fold in flour.\n5. Pour into ramekins and bake 12-14 minutes.\n6. Invert onto plates and serve immediately.",
                Ratings = [5, 5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 9,
                Title = "Classic Cheesecake",
                Category = "Desserts",
                Ingredients = "Cream cheese\nSugar\nEggs\nVanilla extract\nSour cream\nGraham cracker crust",
                Steps = "1. Preheat oven to 325°F (165°C).\n2. Beat cream cheese and sugar until smooth.\n3. Add eggs one at a time, then vanilla and sour cream.\n4. Pour filling into prepared crust.\n5. Bake for 55 minutes, then turn off oven and let cool inside for 1 hour.\n6. Refrigerate at least 4 hours before serving.",
                Ratings = [4, 5, 4, 5]
            }
        ];
        _nextId = 10;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && rating is >= 1 and <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }
}

