@page "/"

@using RecipeShare.Services

@inject RecipeService Recipes

<PageTitle>RecipeShare — Home</PageTitle>

<div class="text-center mb-4">
    <h1>🍳 RecipeShare</h1>
    <p class="lead">Discover and share delicious recipes from around the world.</p>
</div>

<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
    @foreach (var category in categories)
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h3 class="card-title">@GetEmoji(category) @category</h3>
                    <p class="card-text text-muted">
                        @Recipes.GetByCategory(category).Count recipe(s)
                    </p>
                    <a href="category/@category" class="btn btn-outline-primary">Browse Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private IReadOnlyList<string> categories = [];

    protected override void OnInitialized()
    {
        categories = Recipes.GetCategories();
    }

    private static string GetEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Asian" => "🥢",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"

@using RecipeShare.Models
@using RecipeShare.Services

@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h2>@CategoryName Recipes</h2>

@if (recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 g-4 mt-2">
        @foreach (var recipe in recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">
                            @if (recipe.Ratings.Count > 0)
                            {
                                <span class="text-warning">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
                                <span class="text-muted ms-1">(@recipe.AverageRating.ToString("F1"))</span>
                            }
                            else
                            {
                                <span class="text-muted">No ratings yet</span>
                            }
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-sm btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<div class="mt-4">
    <a href="/" class="btn btn-outline-secondary">← Back to Categories</a>
</div>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> recipes = [];

    protected override void OnInitialized()
    {
        recipes = Recipes.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"

@using RecipeShare.Models
@using RecipeShare.Services

@inject RecipeService Recipes

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <h3>Recipe not found</h3>
    <p class="text-muted">The recipe you're looking for doesn't exist.</p>
}
else
{
    <h2>@recipe.Title</h2>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-5">
            <div class="card">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-7">
            <div class="card">
                <div class="card-header"><strong>Steps</strong></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <div class="card mt-4">
        <div class="card-body">
            <h5>Rate this recipe</h5>
            <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />
        </div>
    </div>

    <div class="mt-4">
        <a href="category/@recipe.Category" class="btn btn-outline-secondary">← Back to @recipe.Category</a>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = Recipes.GetById(Id);
    }
}

@using RecipeShare.Services

@inject RecipeService Recipes

@if (submitted)
{
    <p class="text-success fw-bold">
        ★ You rated this @selectedRating out of 5 — thanks!
    </p>
    <p class="text-muted">
        Average: @(Recipes.GetById(RecipeId)?.AverageRating.ToString("F1") ?? "N/A")
        (@(Recipes.GetById(RecipeId)?.Ratings.Count ?? 0) ratings)
    </p>
}
else
{
    <div class="d-flex align-items-center gap-1">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link p-0 fs-3 text-decoration-none"
                    title="Rate @star star(s)"
                    @onclick="() => SubmitRating(star)">
                <span class="@(star <= hoveredStar ? "text-warning" : "text-secondary")"
                      @onmouseover="() => hoveredStar = star"
                      @onmouseout="() => hoveredStar = 0">
                    @(star <= hoveredStar ? "★" : "☆")
                </span>
            </button>
        }
        @if (hoveredStar > 0)
        {
            <span class="ms-2 text-muted">@hoveredStar / 5</span>
        }
    </div>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int hoveredStar;
    private int selectedRating;
    private bool submitted;

    private void SubmitRating(int rating)
    {
        selectedRating = rating;
        Recipes.AddRating(RecipeId, rating);
        submitted = true;
    }
}

